-- =====================================================================
-- MontArarat ERP - Massa de dados (GERADA por sql/ferramentas/gerar_massa.py)
-- Cardápio, preços, fornecedores e formato do caixa vêm das fotos do estabelecimento; vendas, pessoas e quantidades são SIMULADAS.
-- Período simulado: 22/09/2026 a 13/10/2026 (20:15).
-- Ordem de carga respeita as chaves estrangeiras. Executar após os scripts 02 e 03.
--
-- ANOMALIAS INTENCIONAIS (para demonstrar as consultas de auditoria; nenhuma viola CHECK/FK):
--   A) um lote chegou com mais quantidade do que a compra pedia (bacon)
--   B) um recebimento trouxe item que não constava na compra (maionese)
--   C) um pedido com promoção de aniversário sem documento conferido
--   D) um fechamento de caixa com diferença de R$ 42,50
--   E) duas reservas sobrepostas na mesma mesa (uma ficou ATIVA após a data)
--   F) contas a pagar vencidas e ainda em aberto
-- =====================================================================
SET NAMES utf8mb4;
USE montararat_erp;

