-- ---------------------------------------------------------------------
-- CONSUMO: baixa automática de insumos calculada pela ficha técnica (RF04).
-- Regra: quando o preparo começa, cada pedido consome (item x ficha técnica) e
-- (combo x composição x ficha técnica). Os ids continuam após os explícitos acima.
-- ---------------------------------------------------------------------
INSERT INTO movimentacao_estoque
    (id_insumo, id_lote, id_pedido, id_funcionario, tipo_movimentacao, quantidade, data_hora_movimentacao, motivo)
SELECT c.id_insumo, NULL, c.id_pedido, 3, 'CONSUMO', -c.quantidade_consumida,
       p.data_hora_inicio_preparo, 'Baixa automática pela ficha técnica'
FROM v_consumo_pedido_insumo c
JOIN pedido p ON p.id_pedido = c.id_pedido
WHERE p.data_hora_inicio_preparo IS NOT NULL
ORDER BY p.data_hora_inicio_preparo, c.id_pedido, c.id_insumo;

